import AppKit
import ImageIO
import PastyCore
import QuickLookThumbnailing

/// Real previews of copied files (screenshots, photos, PDFs, videos, documents) generated by
/// QuickLook off the main thread and cached. Falls back to the Finder icon when QuickLook has
/// nothing better (or the file is gone).
@MainActor
final class FileThumbnails {
    static let shared = FileThumbnails()

    struct Preview {
        let image: NSImage
        /// Pixel dimensions when the file is an image.
        let pixelSize: CGSize?
    }

    private let cache = NSCache<NSString, NSImage>()
    private let sizes = NSCache<NSString, NSValue>()

    private init() {
        cache.countLimit = 300
    }

    private func key(_ path: String, _ size: CGFloat) -> NSString {
        "\(path)#\(Int(size))" as NSString
    }

    func cached(path: String, size: CGFloat) -> NSImage? {
        cache.object(forKey: key(path, size))
    }

    /// A thumbnail that fits in `size` × `size` points, or nil if the file is missing or QuickLook
    /// can only offer a generic icon.
    func thumbnail(path: String, size: CGFloat) async -> NSImage? {
        if let cached = cached(path: path, size: size) { return cached }
        let url = URL(fileURLWithPath: path)
        guard FileManager.default.fileExists(atPath: path) else { return nil }
        let scale = NSScreen.main?.backingScaleFactor ?? 2
        let request = QLThumbnailGenerator.Request(
            fileAt: url,
            size: CGSize(width: size, height: size),
            scale: scale,
            representationTypes: .thumbnail
        )
        let generated: UncheckedSendable<CGImage>? = await withCheckedContinuation { continuation in
            // @Sendable: QuickLook calls this on a background queue, so it must not inherit the
            // main-actor isolation of the surrounding code (Swift 6 would trap at runtime).
            QLThumbnailGenerator.shared.generateBestRepresentation(for: request) { @Sendable representation, _ in
                continuation.resume(returning: representation.map { UncheckedSendable(value: $0.cgImage) })
            }
        }
        guard let cgImage = generated?.value else { return nil }
        let image = NSImage(cgImage: cgImage, size: NSSize(width: CGFloat(cgImage.width) / scale, height: CGFloat(cgImage.height) / scale))
        cache.setObject(image, forKey: key(path, size))
        return image
    }

    /// Pixel dimensions of an image file (header only), cached.
    func pixelSize(path: String) async -> CGSize? {
        if let cached = sizes.object(forKey: path as NSString) { return cached.sizeValue }
        let url = URL(fileURLWithPath: path)
        let size = await Task.detached(priority: .utility) { () -> CGSize? in
            ImageTools.pixelSize(ofFileAt: url).map { CGSize(width: $0.width, height: $0.height) }
        }.value
        if let size { sizes.setObject(NSValue(size: size), forKey: path as NSString) }
        return size
    }
}
